int main(void){unsigned outcome;while(scanf("%u",&outcome)==1){MoidaDisplay base={0};moida_display_fill(&base,outcome!=48);if(outcome==48){moida_icon_set(&base,100,true);moida_icon_set(&base,311,true);}unsigned ending_index=0;MoidaRandom ghost_random;moida_random_seed(&ghost_random,12345);MoidaResult s;moida_result_init(&s,&base,outcome);if(outcome==90){s.ending_room=ending;s.ending_user=&ending_index;}s.ghost_random=&ghost_random;s.ghost_reveal_icon=100;s.escape_spider=229;s.stats[0]=123;s.stats[1]=45;s.stats[2]=6;s.rescued_count=4;s.rescued_icons[0]=275;s.rescued_icons[1]=277;s.rescued_icons[2]=278;s.rescued_icons[3]=272;s.monster_icon=189;s.monster_spot=190;s.pushing_count=2;s.crown_friend=275;s.help_strand=60;s.hint_strand=64;s.hint_icon=28;s.face_icon=275;s.talk_icon=280;s.rescued_strand=56;s.lock_icon=166;s.search_icon=100;s.tunnel_icon=263;if(outcome==13)s.reward_icon=100;if(outcome==47)s.reward_icon=268;for(unsigned i=0;i<500&&!s.complete;i++){if((outcome>=52||outcome==43||outcome==30||outcome==31||outcome==35)&&i%31==18&&!s.runner.wait)s.runner.waiting_input=false;moida_result_tick(&s);printf("{\"awarded\":%s,\"gaveGift\":%s,\"words\":[",s.award_crown?"true":"false",s.give_gift?"true":"false");for(unsigned j=0;j<20;j++)printf("%s%" PRIu32,j?",":"",s.display.data[j]);printf("],\"hz\":%.2f,\"duration\":%d,\"complete\":%s}\n",s.hz,s.duration,s.complete?"true":"false");}if(!s.complete)return 2;}return 0;}
